/*
 * A291826  Numbers k such that k^5 is sum of 2 nonzero 6th powers.
 * https://oeis.org/A291826
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 3, u32 n <= 19, u64 n <= 25, u128 n <= 25,
 *            big any n
 * Helpers:   pow_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) = nth smallest integer k such that k^5 is the sum of two
 * non‑zero 6th powers.  The sequence can be generated by the identity
 *
 *   k = (i^6) * (j^6 + 1)^5   (i ≥ 1, j ≥ 1)
 *
 * For each fixed j, the values k form an increasing sequence
 * const(j) × i^6 with const(j) = (j^6 + 1)^5.
 * The overall sequence is the merge of all such j‑sequences.
 * Duplicate values (if any) are discarded.
 *
 * The function a(idx_t n) below keeps a sorted list of terms and
 * expands it lazily to supply any requested index n.
 */

#include <stdint.h>
#include <stdlib.h>
#include "../utils/pow_seq.h"

seq_t a(idx_t n)
{
    /* static state ----------------------------------------------------- */
    static seq_t *terms      = NULL; /* sorted terms   */
    static size_t  term_cnt  = 0;     /* number of terms computed */
    static size_t  term_cap  = 0;     /* capacity of terms array   */

    /* tables for j‑sequences ------------------------------------------ */
    static seq_t *base      = NULL; /* base[j] = (j^6 + 1)^5, 1‑based */
    static idx_t *i_next    = NULL; /* next i to use for each j   */
    static idx_t  j_max     = 0;    /* number of j’s currently stored */

    /* helper to grow the terms array ---------------------------------- */
    if (term_cnt == term_cap) {
        term_cap = (term_cap == 0) ? 128 : term_cap * 2;
        terms = (seq_t *)realloc(terms, term_cap * sizeof(seq_t));
    }

    /* determine needed number of j‑sequences ---------------------------- */
    /* For 64‑bit seq_t the largest useful j is 3; larger j produce
     * terms that overflow uint64_t.  For larger seq_t we compute j
     * dynamically from an upper bound that depends on n.
     */
    size_t desired_j_max = j_max;
    if (sizeof(seq_t) <= 8) {          /* 64‑bit build */
        desired_j_max = 3;             /* j = 1,2,3 are enough */
    } else {
        /* upper bound: 32 * n^6  (fits in seq_t for the sizes we target) */
        seq_t ub = pow_seq((seq_t)n, 6);
        ub = ub * ((seq_t)32);

        /* extend j_max while base(j) ≤ ub */
        while (1) {
            idx_t next_j = desired_j_max + 1;
            seq_t j6 = pow_seq((seq_t)next_j, 6);
            seq_t j6p1 = j6 + ((seq_t)1);
            seq_t base_j = pow_seq(j6p1, 5);
            if (base_j > ub)
                break;
            ++desired_j_max;
        }
    }

    /* add new j‑entries if required ------------------------------------ */
    if (desired_j_max > j_max) {
        base  = (seq_t *)realloc(base,  (desired_j_max + 1) * sizeof(seq_t));
        i_next = (idx_t *)realloc(i_next, (desired_j_max + 1) * sizeof(idx_t));
        for (idx_t j = j_max + 1; j <= desired_j_max; ++j) {
            seq_t j6 = pow_seq((seq_t)j, 6);
            seq_t j6p1 = j6 + ((seq_t)1);
            base[j] = pow_seq(j6p1, 5);   /* (j^6 + 1)^5 */
            i_next[j] = 1;                /* start with i = 1 */
        }
        j_max = desired_j_max;
    }

    /* generate terms until we have at least n of them ------------------- */
    while (term_cnt < n) {
        /* find the smallest candidate among all j‑sequences */
        seq_t  min_val = 0;
        idx_t  best_j  = 0;
        for (idx_t j = 1; j <= j_max; ++j) {
            seq_t candidate = base[j] * pow_seq((seq_t)i_next[j], 6);
            if (best_j == 0 || candidate < min_val) {
                min_val = candidate;
                best_j = j;
            }
        }

        /* record unique value */
        if (term_cnt == 0 || min_val != terms[term_cnt - 1]) {
            /* grow terms array if necessary */
            if (term_cnt == term_cap) {
                term_cap = (term_cap == 0) ? 128 : term_cap * 2;
                terms = (seq_t *)realloc(terms, term_cap * sizeof(seq_t));
            }
            terms[term_cnt++] = min_val;
        }

        /* advance the chosen j‑sequence */
        ++i_next[best_j];
    }

    /* return the requested term (offset 1) */
    return terms[n - 1];
}
